{"file_path":"src/nodes.js","content":"// Node kinds: 'table', 'aot' (array of tables), 'array', 'string', 'integer', 'float', 'boolean'

export function newTable(path) {
  return { kind: 'table', map: new Map(), headerDefined: false, path }
}

export function pathToStr(segs) {
  let s = ''
  for (const seg of segs) {
    if (typeof seg === 'number') {
      s += `[${seg}]`
    } else {
      s += s === '' ? seg : '.' + seg
    }
  }
  return s
}
"}

