{"file_path":"src/lineParser.js","content":"import { fail } from './errors.js'
import { newTable } from './nodes.js'

const DIGITS = '\\d+(?:_\\d+)*'
const INT_RE = new RegExp(`^[+-]?${DIGITS}$`)
const FLOAT_RE = new RegExp(`^[+-]?${DIGITS}(?:\\.${DIGITS})?(?:[eE][+-]?${DIGITS})?$`)

const BARE_NAME_CHAR = /[A-Za-z0-9_-]/

export class LineParser {
  constructor(line, lineNo) {
    this.line = line
    this.lineNo = lineNo
    this.pos = 0
  }

  atEnd() {
    return this.pos >= this.line.length
  }

  peek() {
    return this.line[this.pos]
  }

  error(reason) {
    fail(this.lineNo, reason)
  }

  skipWS() {
    while (!this.atEnd() && (this.peek() === ' ' || this.peek() === '\t')) this.pos++
  }

  // --- names ---

  parseName() {
    if (this.atEnd()) this.error('expected a name')
    const c = this.peek()
    if (c === '"') return this.parseBasicStringRaw()
    if (c === "'") return this.parseLiteralStringRaw()
    const start = this.pos
    while (!this.atEnd() && BARE_NAME_CHAR.test(this.peek())) this.pos++
    if (this.pos === start) this.error('expected a name')
    return this.line.slice(start, this.pos)
  }

  parseDottedName() {
    const names = [this.parseName()]
    while (true) {
      this.skipWS()
      if (!this.atEnd() && this.peek() === '.') {
        this.pos++
        this.skipWS()
        names.push(this.parseName())
      } else {
        break
      }
    }
    return names
  }

  // --- strings ---

  parseBasicStringRaw() {
    this.pos++ // opening quote
    let out = ''
    while (true) {
      if (this.atEnd()) this.error('unterminated string')
      const c = this.line[this.pos]
      if (c === '"') {
        this.pos++
        return out
      }
      if (c === '\\') {
        this.pos++
        if (this.atEnd()) this.error('unterminated string')
        const e = this.line[this.pos]
        switch (e) {
          case '"':
            out += '"'
            this.pos++
            break
          case '\\':
            out += '\\'
            this.pos++
            break
          case 'n':
            out += '\n'
            this.pos++
            break
          case 't':
            out += '\t'
            this.pos++
            break
          case 'r':
            out += '\r'
            this.pos++
            break
          case '0':
            out += '\0'
            this.pos++
            break
          case 'u': {
            const hex = this.line.slice(this.pos + 1, this.pos + 5)
            if (hex.length < 4 || !/^[0-9A-Fa-f]{4}$/.test(hex)) {
              this.error('invalid escape \\u')
            }
            out += String.fromCharCode(parseInt(hex, 16))
            this.pos += 5
            break
          }
          default:
            this.error('invalid escape \\' + e)
        }
      } else {
        out += c
        this.pos++
      }
    }
  }

  parseLiteralStringRaw() {
    this.pos++ // opening quote
    const start = this.pos
    while (true) {
      if (this.atEnd()) this.error('unterminated string')
      if (this.line[this.pos] === "'") {
        const out = this.line.slice(start, this.pos)
        this.pos++
        return out
      }
      this.pos++
    }
  }

  // --- values ---

  parseValue(basePath) {
    this.skipWS()
    if (this.atEnd() || ',]}'.includes(this.peek())) this.error('expected a value')
    const c = this.peek()
    if (c === '"') return { kind: 'string', value: this.parseBasicStringRaw() }
    if (c === "'") return { kind: 'string', value: this.parseLiteralStringRaw() }
    if (c === '[') return this.parseArray(basePath)
    if (c === '{') return this.parseInlineTable(basePath)
    const start = this.pos
    while (!this.atEnd() && !' \t,]}'.includes(this.peek())) this.pos++
    const token = this.line.slice(start, this.pos)
    if (token === 'true') return { kind: 'boolean', value: true }
    if (token === 'false') return { kind: 'boolean', value: false }
    if (INT_RE.test(token)) return { kind: 'integer', value: parseIntegerToken(token) }
    if (FLOAT_RE.test(token)) return { kind: 'float', value: parseFloatToken(token) }
    this.error('invalid value ' + token)
  }

  parseArray(basePath) {
    this.pos++ // '['
    const items = []
    let idx = 0
    while (true) {
      this.skipWS()
      if (this.atEnd()) this.error('unterminated array')
      if (this.peek() === ']') {
        this.pos++
        return { kind: 'array', items }
      }
      const val = this.parseValue(basePath.concat([idx]))
      items.push(val)
      idx++
      this.skipWS()
      if (this.atEnd()) this.error('unterminated array')
      const c = this.peek()
      if (c === ',') {
        this.pos++
        continue
      }
      if (c === ']') {
        this.pos++
        return { kind: 'array', items }
      }
      this.error('unterminated array')
    }
  }

  parseInlineTable(basePath) {
    this.pos++ // '{'
    const tableNode = newTable(basePath)
    this.skipWS()
    if (!this.atEnd() && this.peek() === '}') {
      this.pos++
      return tableNode
    }
    while (true) {
      this.skipWS()
      if (this.atEnd()) this.error('unterminated inline table')
      const names = this.parseDottedName()
      this.skipWS()
      if (this.atEnd() || this.peek() !== '=') this.error('expected = in an inline table')
      this.pos++
      this.skipWS()
      resolveAndAssign(this, tableNode, names, basePath)
      this.skipWS()
      if (this.atEnd()) this.error('unterminated inline table')
      const c = this.peek()
      if (c === ',') {
        this.pos++
        continue
      }
      if (c === '}') {
        this.pos++
        return tableNode
      }
      this.error('unterminated inline table')
    }
  }
}

function parseIntegerToken(token) {
  const norm = token.replace(/_/g, '')
  const n = Number(norm)
  if (Number.isSafeInteger(n)) return n
  try {
    return BigInt(norm)
  } catch {
    return n
  }
}

function parseFloatToken(token) {
  const norm = token.replace(/_/g, '')
  return Number(norm)
}

// Resolves the dotted `names` inside `tableNode` (whose absolute path is
// `basePath`), checks for duplicate keys, parses the value, and assigns it.
function resolveAndAssign(lineParser, tableNode, names, basePath) {
  let node = tableNode
  const curPath = basePath.slice()
  for (let i = 0; i < names.length - 1; i++) {
    const seg = names[i]
    curPath.push(seg)
    let child = node.map.get(seg)
    if (child === undefined) {
      child = newTable(curPath.slice())
      node.map.set(seg, child)
    } else if (child.kind === 'table') {
      // fine
    } else if (child.kind === 'aot') {
      child = child.items[child.items.length - 1]
    } else {
      lineParser.error(`${pathJoin(curPath)} is not a table`)
    }
    node = child
  }
  const finalKey = names[names.length - 1]
  curPath.push(finalKey)
  if (node.map.has(finalKey)) {
    lineParser.error(`key ${pathJoin(curPath)} is defined twice`)
  }
  const value = lineParser.parseValue(curPath)
  node.map.set(finalKey, value)
}

function pathJoin(segs) {
  let s = ''
  for (const seg of segs) {
    if (typeof seg === 'number') {
      s += `[${seg}]`
    } else {
      s += s === '' ? seg : '.' + seg
    }
  }
  return s
}

export { resolveAndAssign }
"}

