{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import fs from 'node:fs'
import { parseDocument } from './document.js'
import { toJSON, toKeys } from './format.js'
import { ConfError } from './errors.js'

const mode = process.argv[2]

if (process.argv.length !== 3 || (mode !== 'json' && mode !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

let input
try {
  input = fs.readFileSync(0, 'utf8')
} catch {
  input = ''
}

try {
  const root = parseDocument(input)
  if (mode === 'json') {
    process.stdout.write(toJSON(root) + '\n')
  } else {
    const lines = toKeys(root)
    process.stdout.write(lines.length === 0 ? '' : lines.map((l) => l + '\n').join(''))
  }
  process.exit(0)
} catch (err) {
  if (err instanceof ConfError) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(2)
  }
  throw err
}
"}

