      if (parser.atEnd() || parser.peek() !== '=') parser.error('expected key = value')
      parser.pos++
      parser.skipWS()
      resolveAndAssign(parser, current, names, current.path)
      parser.skipWS()
      if (!parser.atEnd() && parser.peek() !== '#' && parser.peek() !== ';') {
        parser.error('trailing text after a value')
      }
    }
  }

  return rootTable
}
"}

{"file_path":"src/format.js","content":"function indentStr(n) {
  return '  '.repeat(n)
}

function formatScalarJSON(node) {
  switch (node.kind) {
    case 'string':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
      return typeof node.value === 'bigint' ? node.value.toString() : String(node.value)
    case 'float':
      return JSON.stringify(node.value)
    default:
      throw new Error('not a scalar: ' + node.kind)
  }
}

export function toJSON(node, indent = 0) {
  switch (node.kind) {
    case 'table': {
      const keys = Array.from(node.map.keys()).sort()
      if (keys.length === 0) return '{}'
      const inner = keys
        .map((k) => indentStr(indent + 1) + JSON.stringify(k) + ': ' + toJSON(node.map.get(k), indent + 1))
        .join(',\n')
      return '{\n' + inner + '\n' + indentStr(indent) + '}'
    }
    case 'aot':
    case 'array': {
      const items = node.kind === 'aot' ? node.items : node.items
      if (items.length === 0) return '[]'
      const inner = items.map((it) => indentStr(indent + 1) + toJSON(it, indent + 1)).join(',\n')
      return '[\n' + inner + '\n' + indentStr(indent) + ']'
    }
    default:
      return formatScalarJSON(node)
  }
}

const TYPE_NAMES = {
  table: 'table',
  aot: 'array',
  array: 'array',
  string: 'string',
  integer: 'integer',
  float: 'float',
  boolean: 'boolean',
}

function pathText(segs) {
  let s = ''
  for (const seg of segs) {
    if (typeof seg === 'number') {
      s += `[${seg}]`
    } else {
      s += s === '' ? seg : '.' + seg
    }
  }
  return s
}

function walkKeys(node, pathSegs, out) {
  out.push(pathText(pathSegs) + ' ' + TYPE_NAMES[node.kind])
  if (node.kind === 'table') {
    const keys = Array.from(node.map.keys()).sort()
    for (const k of keys) walkKeys(node.map.get(k), pathSegs.concat([k]), out)
  } else if (node.kind === 'aot' || node.kind === 'array') {
    node.items.forEach((it, i) => walkKeys(it, pathSegs.concat([i]), out))
  }
}

export function toKeys(root) {
  const out = []
  const keys = Array.from(root.map.keys()).sort()
  for (const k of keys) walkKeys(root.map.get(k), [k], out)
  return out
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import fs from 'node:fs'
import { parseDocument } from './document.js'
import { toJSON, toKeys } from './format.js'
import { ConfError } from './errors.js'

const mode = process.argv[2]

if (process.argv.length !== 3 || (mode !== 'json' && mode !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

let input
try {
  input = fs.readFileSync(0, 'utf8')
} catch {
  input = ''
}

try {
  const root = parseDocument(input)
  if (mode === 'json') {
    process.stdout.write(toJSON(root) + '\n')
  } else {
    const lines = toKeys(root)
    process.stdout.write(lines.length === 0 ? '' : lines.map((l) => l + '\n').join(''))
  }
  process.exit(0)
} catch (err) {
  if (err instanceof ConfError) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(2)
  }
  throw err
}
"}

